package dev.eugheist.ttmodern;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.fml.event.lifecycle.FMLClientSetupEvent;
import net.neoforged.neoforge.client.event.RegisterColorHandlersEvent;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.api.distmarker.Dist;
@EventBusSubscriber(modid="ttinkerer",bus=EventBusSubscriber.Bus.MOD,value=Dist.CLIENT)
public final class ClientSetup {
    @SubscribeEvent public static void screens(net.neoforged.neoforge.client.event.RegisterMenuScreensEvent event){if(net.neoforged.fml.ModList.get().isLoaded("computercraft"))event.register(AspectAnalyzer.MENU.get(),AspectAnalyzerScreen::new);if(KamiStartupConfig.enabled())event.register(WarpGateMenu.TYPE.get(),WarpGateScreen::new);event.register(ThaumicTinkererModern.ENCHANTER_MENU.get(),EnchanterScreen::new);if(KamiStartupConfig.enabled())event.register(IchorPouchMenu.TYPE.get(),IchorPouchScreen::new);event.register(ThaumicTinkererModern.MAGNET_MENU.get(),MagnetScreen::new);event.register(ThaumicTinkererModern.ANIMATION_TABLET_MENU.get(),AnimationTabletScreen::new);}
    @SubscribeEvent public static void renderers(net.neoforged.neoforge.client.event.EntityRenderersEvent.RegisterRenderers event){if(net.neoforged.fml.ModList.get().isLoaded("computercraft"))event.registerBlockEntityRenderer(GolemConnector.ENTITY.get(),GolemConnectorRenderer::new);if(KamiStartupConfig.enabled())event.registerBlockEntityRenderer(WarpGateBlock.ENTITY.get(),WarpGateRenderer::new);event.registerBlockEntityRenderer(ThaumicTinkererModern.PLATFORM_ENTITY.get(),PlatformRenderer::new);event.registerBlockEntityRenderer(ThaumicTinkererModern.ANIMATION_TABLET_ENTITY.get(),AnimationTabletRenderer::new);event.registerBlockEntityRenderer(ThaumicTinkererModern.DISLOCATOR_ENTITY.get(),DislocatorRenderer::new);event.registerBlockEntityRenderer(ThaumicTinkererModern.TRANSVECTOR_ENTITY.get(),TransvectorRenderer::new);event.registerBlockEntityRenderer(ThaumicTinkererModern.FUNNEL_ENTITY.get(),FunnelRenderer::new);event.registerBlockEntityRenderer(ThaumicTinkererModern.REPAIRER_ENTITY.get(),RepairerRenderer::new);}
    @SubscribeEvent public static void setup(FMLClientSetupEvent event){event.enqueueWork(()->{if(KamiStartupConfig.enabled()){net.minecraft.client.renderer.item.ItemProperties.register(AwakenedSword.ITEM.get(),net.minecraft.resources.ResourceLocation.fromNamespaceAndPath("ttinkerer","tool_mode"),(stack,level,entity,seed)->AdvancedToolModes.get(stack));net.minecraft.client.renderer.item.ItemProperties.register(AwakenedAxe.ITEM.get(),net.minecraft.resources.ResourceLocation.fromNamespaceAndPath("ttinkerer","tool_mode"),(stack,level,entity,seed)->AdvancedToolModes.get(stack));net.minecraft.client.renderer.item.ItemProperties.register(AwakenedShovel.ITEM.get(),net.minecraft.resources.ResourceLocation.fromNamespaceAndPath("ttinkerer","tool_mode"),(stack,level,entity,seed)->AdvancedToolModes.get(stack));net.minecraft.client.renderer.item.ItemProperties.register(AwakenedPick.ITEM.get(),net.minecraft.resources.ResourceLocation.fromNamespaceAndPath("ttinkerer","tool_mode"),(stack,level,entity,seed)->AdvancedToolModes.get(stack));}net.minecraft.client.renderer.item.ItemProperties.register(ThaumicTinkererModern.INFUSED_SEEDS.get(),net.minecraft.resources.ResourceLocation.fromNamespaceAndPath("ttinkerer","seed_aspect"),(stack,level,entity,seed)->InfusedSeedData.read(stack).mainAspect()==null?0:InfusedGrainBlock.texture(InfusedSeedData.read(stack).mainAspect()));if(KamiStartupConfig.enabled())net.minecraft.client.renderer.item.ItemProperties.register(BlockTalisman.ITEM.get(),net.minecraft.resources.ResourceLocation.fromNamespaceAndPath("ttinkerer","active"),(stack,level,entity,seed)->BlockTalisman.active(stack)?1:0);net.minecraft.client.renderer.item.ItemProperties.register(ThaumicTinkererModern.BLOOD_SWORD.get(),net.minecraft.resources.ResourceLocation.fromNamespaceAndPath("ttinkerer","active"),(stack,level,entity,seed)->BloodSwordItem.active(stack)?1:0);net.minecraft.client.renderer.item.ItemProperties.register(ThaumicTinkererModern.CLEANSING_TALISMAN.get(),net.minecraft.resources.ResourceLocation.fromNamespaceAndPath("ttinkerer","enabled"),(stack,level,entity,seed)->CleansingTalismanItem.enabled(stack)?1:0);net.minecraft.client.renderer.item.ItemProperties.register(ThaumicTinkererModern.XP_TALISMAN.get(),net.minecraft.resources.ResourceLocation.fromNamespaceAndPath("ttinkerer","enabled"),(stack,level,entity,seed)->XPTalismanItem.enabled(stack)?1:0);});}
    @SubscribeEvent public static void colors(RegisterColorHandlersEvent.Item event){
        event.register((stack,layer)->java.awt.Color.HSBtoRGB(.75f,(stack.getMaxDamage()-stack.getDamageValue())/(float)stack.getMaxDamage()*.5f,1),ThaumicTinkererModern.SPELL_CLOTH.get());
    }
}
